import java.util.*;
public class ManualEqualsHashCodeDemo {
  public static void main(String[] args) {
    class Key { final String project; final int revision; Key(String p,int r){project=p;revision=r;} public boolean equals(Object o){return this==o || (o instanceof Key k && revision==k.revision && java.util.Objects.equals(project,k.project));} public int hashCode(){return java.util.Objects.hash(project,revision);} }
    var a=new Key("A",2); var b=new Key("A",2); System.out.println(a.equals(b)+" "+(a.hashCode()==b.hashCode()));
  }
}
